import{_ as r,I as o,c as s,o as a,a3 as t,b as l,w as i,a as d,J as g,a4 as p}from"./chunks/framework.MI-M1z4O.js";const _=JSON.parse('{"title":"Root Causes and Mitigation Strategies for Post-Fine-Tuning LLM Performance Degradation","description":"Underlying mechanisms of general reasoning degradation (catastrophic forgetting) during domain-specific LLM fine-tuning, along with LoRA hyperparameter optimization and regularization replay techniques.","frontmatter":{"title":"Root Causes and Mitigation Strategies for Post-Fine-Tuning LLM Performance Degradation","shortTitle":"Fine-Tuning Degradation Analysis","description":"Underlying mechanisms of general reasoning degradation (catastrophic forgetting) during domain-specific LLM fine-tuning, along with LoRA hyperparameter optimization and regularization replay techniques.","category":"AI Research","sort":500,"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/en/study/llm-finetuning-degradation-analysis"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/study/llm-finetuning-degradation-analysis"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/study/llm-finetuning-degradation-analysis"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/study/llm-finetuning-degradation-analysis"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/study/llm-finetuning-degradation-analysis"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"Root Causes and Mitigation Strategies for Post-Fine-Tuning LLM Performance Degradation | Empasy Docs"}],["meta",{"property":"og:description","content":"Underlying mechanisms of general reasoning degradation (catastrophic forgetting) during domain-specific LLM fine-tuning, along with LoRA hyperparameter optimization and regularization replay techniques."}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/study/llm-finetuning-degradation-analysis"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Root Causes and Mitigation Strategies for Post-Fine-Tuning LLM Performance Degradation | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Underlying mechanisms of general reasoning degradation (catastrophic forgetting) during domain-specific LLM fine-tuning, along with LoRA hyperparameter optimization and regularization replay techniques."}]]},"headers":[],"relativePath":"en/study/llm-finetuning-degradation-analysis.md","filePath":"en/study/llm-finetuning-degradation-analysis.md","lastUpdated":1795293539000}'),h={name:"en/study/llm-finetuning-degradation-analysis.md"};function c(m,e,f,u,y,k){const n=o("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="root-causes-and-mitigation-strategies-for-post-fine-tuning-llm-performance-degradation" tabindex="-1">Root Causes and Mitigation Strategies for Post-Fine-Tuning LLM Performance Degradation <a class="header-anchor" href="#root-causes-and-mitigation-strategies-for-post-fine-tuning-llm-performance-degradation" aria-label="Permalink to “Root Causes and Mitigation Strategies for Post-Fine-Tuning LLM Performance Degradation”">​</a></h1><h2 id="_1-overview-and-problem-statement" tabindex="-1">1. Overview and Problem Statement <a class="header-anchor" href="#_1-overview-and-problem-statement" aria-label="Permalink to “1. Overview and Problem Statement”">​</a></h2><p>When fine-tuning a foundation model for domain-specific tasks (such as SQL generation, internal policy QA, or medical/financial analysis), accuracy on the target task improves, yet <strong>core capabilities—such as general reasoning, mathematical problem solving, multilingual translation, and coding—frequently suffer sharp degradation</strong>.</p><p>In academic literature, this phenomenon is referred to as <strong>Catastrophic Forgetting</strong> or the <strong>Alignment Tax</strong>, and resolving it is a critical challenge when building enterprise AI systems.</p><hr><h2 id="_2-four-core-causes-of-performance-degradation" tabindex="-1">2. Four Core Causes of Performance Degradation <a class="header-anchor" href="#_2-four-core-causes-of-performance-degradation" aria-label="Permalink to “2. Four Core Causes of Performance Degradation”">​</a></h2>',6)),(a(),l(p,null,{default:i(()=>[g(n,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Degradation%5B%22Post-Fine-Tuning%20Performance%20Degradation%22%5D%0A%20%20%20%20Degradation%20--%3E%20Cause1%5B%221.%20Catastrophic%20Forgetting%3Cbr%2F%3E(Abrupt%20Shift%20in%20Weight%20Space)%22%5D%0A%20%20%20%20Degradation%20--%3E%20Cause2%5B%222.%20Overfitting%20and%20Loss%20of%20Diversity%3Cbr%2F%3E(Overfitting%20to%20Narrow%20Format)%22%5D%0A%20%20%20%20Degradation%20--%3E%20Cause3%5B%223.%20LoRA%20Rank%20and%20Alpha%20Imbalance%3Cbr%2F%3E(Rank%20Saturation%20%26%20Scaling)%22%5D%0A%20%20%20%20Degradation%20--%3E%20Cause4%5B%224.%20Label%20Noise%20%26%20Data%20Contamination%3Cbr%2F%3E(Format%20Inconsistency)%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t(`<h3 id="_2-1-abrupt-displacement-in-weight-space-catastrophic-forgetting" tabindex="-1">2.1 Abrupt Displacement in Weight Space (Catastrophic Forgetting) <a class="header-anchor" href="#_2-1-abrupt-displacement-in-weight-space-catastrophic-forgetting" aria-label="Permalink to “2.1 Abrupt Displacement in Weight Space (Catastrophic Forgetting)”">​</a></h3><p>A foundation model develops balanced weights across a broad multidimensional manifold during pre-training on trillions of tokens.<br> Applying full fine-tuning on a small domain dataset or using an excessively high learning rate pushes the weights out of the existing optimization basin into a local optimum biased solely toward the target task.</p><h3 id="_2-2-output-format-overfitting" tabindex="-1">2.2 Output Format Overfitting <a class="header-anchor" href="#_2-2-output-format-overfitting" aria-label="Permalink to “2.2 Output Format Overfitting”">​</a></h3><p>When training forces rigid JSON templates or short response formats, the model begins <strong>surface pattern mimicking</strong> rather than reasoning about underlying causal relationships, exhibiting fragility even under minor prompt variations.</p><h3 id="_2-3-lora-low-rank-adaptation-hyperparameter-mismatch" tabindex="-1">2.3 LoRA (Low-Rank Adaptation) Hyperparameter Mismatch <a class="header-anchor" href="#_2-3-lora-low-rank-adaptation-hyperparameter-mismatch" aria-label="Permalink to “2.3 LoRA (Low-Rank Adaptation) Hyperparameter Mismatch”">​</a></h3><p>When using LoRA, a Parameter-Efficient Fine-Tuning (PEFT) method, misconfiguring the ratio between $r$ (Rank) and $\\alpha$ (Alpha) or the learning rate causes weight update magnitudes to overwrite the model&#39;s base knowledge: $$\\Delta W = \\frac{\\alpha}{r} (B \\times A)$$</p><ul><li>If $r$ is too large (e.g., $r=128$), the risk of destroying the foundation model&#39;s generalization capability increases significantly.</li><li>If the $\\alpha / r$ ratio exceeds 2.0, update magnitudes grow excessively large, accelerating destructive loss of prior knowledge.</li></ul><hr><h2 id="_3-empirical-mitigations-and-solutions" tabindex="-1">3. Empirical Mitigations and Solutions <a class="header-anchor" href="#_3-empirical-mitigations-and-solutions" aria-label="Permalink to “3. Empirical Mitigations and Solutions”">​</a></h2><h3 id="_3-1-general-domain-data-replay-mixing" tabindex="-1">3.1 General Domain Data Replay Mixing <a class="header-anchor" href="#_3-1-general-domain-data-replay-mixing" aria-label="Permalink to “3.1 General Domain Data Replay Mixing”">​</a></h3><p>The most effective mitigation is mixing a <strong>5% to 15% ratio of a high-quality general instruction replay dataset</strong> into the domain-specific training dataset.</p><div class="language-python"><button title="Copy code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Dataset mixing ratio example (PyTorch Dataset)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">domain_samples </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> load_domain_dataset()       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 85% (Domain-specific data)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">general_samples </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> load_alpaca_eval_mix()     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 15% (General reasoning, math, and coding regularization data)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">training_dataset </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ConcatDataset([domain_samples, general_samples])</span></span></code></pre></div><ul><li><strong>Effect</strong>: The loss function continuously incorporates gradients for general reasoning capabilities, keeping weights anchored within the existing manifold region.</li></ul><h3 id="_3-2-lora-hyperparameter-golden-rules" tabindex="-1">3.2 LoRA Hyperparameter Golden Rules <a class="header-anchor" href="#_3-2-lora-hyperparameter-golden-rules" aria-label="Permalink to “3.2 LoRA Hyperparameter Golden Rules”">​</a></h3><ol><li><strong>Recommended Rank and Alpha Settings</strong>: <ul><li>$r = 16$ or $r = 32$ (sufficient for most downstream tasks)</li><li>$\\alpha = 16$ or $\\alpha = 32$ ($\\frac{\\alpha}{r} = 1.0$)</li></ul></li><li><strong>Target Module Expansion</strong>: Rather than training only <code>q_proj</code> and <code>v_proj</code>, applying low-rank adapters across all linear layers (<code>q, k, v, o, gate, up, down</code>) minimizes catastrophic forgetting.</li><li><strong>Weight Decay and Cosine Scheduler</strong>: <ul><li>Apply a Cosine Annealing Learning Rate Schedule</li><li>Set Warmup ratio between 0.05 and 0.1</li></ul></li></ol><h3 id="_3-3-introducing-neftune-noisy-embedding-fine-tuning" tabindex="-1">3.3 Introducing NEFTune (Noisy Embedding Fine-Tuning) <a class="header-anchor" href="#_3-3-introducing-neftune-noisy-embedding-fine-tuning" aria-label="Permalink to “3.3 Introducing NEFTune (Noisy Embedding Fine-Tuning)”">​</a></h3><p>Injecting subtle Gaussian noise into the embedding layer prevents the model from overfitting to surface token topologies: $$\\tilde{E} = E + \\frac{\\alpha}{\\sqrt{L \\cdot d}} \\cdot \\text{Uniform}(-1, 1)$$</p><ul><li>This proves highly effective at suppressing rote memorization of training answer patterns while preserving semantic reasoning ability.</li></ul><hr><h2 id="_4-verification-checklist-and-benchmark-pipeline" tabindex="-1">4. Verification Checklist and Benchmark Pipeline <a class="header-anchor" href="#_4-verification-checklist-and-benchmark-pipeline" aria-label="Permalink to “4. Verification Checklist and Benchmark Pipeline”">​</a></h2><p>After fine-tuning and prior to production deployment, <strong>regression checks on foundational benchmarks must be verified</strong> alongside domain scores:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Evaluation Metric</th><th style="text-align:left;">Target Capability</th><th style="text-align:left;">Passing Threshold</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Domain Benchmark</strong></td><td style="text-align:left;">Domain-specific precision and recall</td><td style="text-align:left;"><strong>+15% or higher improvement</strong> over base model</td></tr><tr><td style="text-align:left;"><strong>MMLU / ARC</strong></td><td style="text-align:left;">General knowledge and commonsense reasoning</td><td style="text-align:left;"><strong>Within -3%</strong> of base model</td></tr><tr><td style="text-align:left;"><strong>GSM8K</strong></td><td style="text-align:left;">Multi-step mathematical reasoning</td><td style="text-align:left;"><strong>Within -5%</strong> of base model</td></tr><tr><td style="text-align:left;"><strong>HumanEval</strong></td><td style="text-align:left;">Python coding and syntax generation</td><td style="text-align:left;"><strong>Within -5%</strong> of base model</td></tr></tbody></table>`,22))])}const D=r(h,[["render",c]]);export{_ as __pageData,D as default};
